l' => (bool) ($data['user_install'] ?? false), 'eggs' => $data['eggs'] ?? [], 'nodes' => $data['nodes'] ?? [], 'console_images' => (bool) ($data['console_images'] ?? false), 'disabled' => $disabled, 'slots' => (int) $data['slots'], ]); $after = BotConfig::all(); if ($after['disabled'] !== $before['disabled'] && BotConfig::personal() && BotConfig::enabled()) { Artisan::queue('dezerx:discord-sync'); } $capacity = BotConfig::workerCapacity(); $warning = $capacity !== null && $after['slots'] > $capacity['recommended'] ? sprintf( ' Heads up: %d full-quality slots is more than the %d recommended for this server\'s %d PHP workers. A busy Discord can make the panel slow for everyone.', $after['slots'], $capacity['recommended'], $capacity['workers'], ) : null; return $this->afterChange('Discord bot settings saved.' . ($warning ?? ''), $warning !== null); } public function saveBot(Request $request): RedirectResponse { $global = BotConfig::globalBot(); if ($global === null) { return redirect()->route('admin.dezerx.discordbot'); } $data = $request->validate([ 'design' => ['sometimes', 'array'], 'commands' => ['sometimes', 'array'], ]); $commands = []; foreach (array_keys(BotSettings::CATALOGUE) as $name) { $commands[$name] = ['enabled' => (bool) ($data['commands'][$name]['enabled'] ?? false)]; } $design = (array) ($data['design'] ?? []); $design['banner'] = (bool) ($design['banner'] ?? false); $design['logos'] = (bool) ($design['logos'] ?? false); BotSettings::save($global, $design, $commands); return $this->afterChange('Commands and design saved.'); } public function preview(Request $request): JsonResponse { $data = $request->validate([ 'design' => ['sometimes', 'array'], 'commands' => ['sometimes', 'array'], ]); $commands = null; if (isset($data['commands'])) { $commands = []; foreach (array_keys(BotSettings::CATALOGUE) as $name) { $commands[$name] = ['enabled' => (bool) ($data['commands'][$name]['enabled'] ?? false)]; } } $design = isset($data['design']) ? (array) $data['design'] : null; if ($design !== null) { $design['banner'] = (bool) ($design['banner'] ?? false); $design['logos'] = (bool) ($design['logos'] ?? false); } return new JsonResponse(['previews' => Preview::gallery(BotConfig::globalBot(), $design, $commands)]); } public function token(Request $request): RedirectResponse { $data = $request->validate([ 'token' => ['required', 'string', 'min:50', 'max:120'], 'client_secret' => ['nullable', 'string', 'min:20', 'max:100'], ]); $token = (string) preg_replace('/^Bot\s+/i', '', trim($data['token'])); $application = $this->rest->application($token); if ($application === null || $application['public_key'] === '') { $this->alert->danger('Discord did not accept that token. Copy it from the Bot page of the application, and make sure it is the bot token, not the client secret.')->flash(); return redirect()->route('admin.dezerx.discordbot'); } if (DiscordBot::query()->whereNotNull('user_id')->where('application_id', $application['id'])->exists()) { $this->alert->danger('That application is already connected as a customer\'s own bot. Use a separate application for the panel-wide bot.')->flash(); return redirect()->route('admin.dezerx.discordbot'); } $bot = BotConfig::globalBot() ?? new DiscordBot(['user_id' => null]); if ($bot->exists && $bot->application_id !== $application['id']) { $bot->commands_hash = null; $bot->client_secret = null; } $bot->fill([ 'application_id' => $application['id'], 'public_key' => $application['public_key'], 'token' => $token, 'owner_ids' => $application['owner_ids'], 'name' => mb_substr($application['name'], 0, 191), 'avatar' => $application['icon'], ]); if (trim((string) ($data['client_secret'] ?? '')) !== '') { $bot->client_secret = trim((string) $data['client_secret']); } $bot->save(); $sync = $this->rest->syncCommands($bot, true); $this->alert->{$sync['ok'] ? 'success' : 'warning'}('Connected ' . e($application['name']) . '. ' . $sync['message'] . ' Now paste the interactions endpoint URL below into the Developer Portal.')->flash(); return redirect()->route('admin.dezerx.discordbot'); } public function secret(Request $request): RedirectResponse { $bot = BotConfig::globalBot(); $data = $request->validate(['client_secret' => ['required', 'string', 'min:20', 'max:100']]); if ($bot !== null) { $bot->forceFill(['client_secret' => trim($data['client_secret'])])->save(); $this->alert->success('Client secret saved. Customers can now link their Discord from their account page.')->flash(); } return redirect()->route('admin.dezerx.discordbot'); } public function sync(): RedirectResponse { $bot = BotConfig::globalBot(); if ($bot !== null) { $sync = $this->rest->syncCommands($bot, true); $this->alert->{$sync['ok'] ? 'success' : 'danger'}($sync['message'])->flash(); } return redirect()->route('admin.dezerx.discordbot'); } public function removeGlobal(): RedirectResponse { BotConfig::globalBot()?->delete(); $this->alert->success('The panel-wide bot was disconnected. Its alerts went with it. The application itself still exists in the Discord Developer Portal.')->flash(); return redirect()->route('admin.dezerx.discordbot'); } public function deleteMember(DiscordBotMember $member): RedirectResponse { $this->linker->unlink($member); $this->alert->success('That account was unlinked and the bot\'s API key for it deleted.')->flash(); return redirect()->route('admin.dezerx.discordbot'); } public function deleteBot(DiscordBot $bot): RedirectResponse { if (!$bot->isGlobal()) { $this->linker->forgetBot($bot); $this->alert->success('That customer\'s bot was disconnected and its API key deleted.')->flash(); } return redirect()->route('admin.dezerx.discordbot'); } public function deleteAlert(DiscordBotAlert $alert): RedirectResponse { $alert->delete(); $this->alert->success('That alert was removed.')->flash(); return redirect()->route('admin.dezerx.discordbot'); } private function afterChange(string $message, bool $warn = false): RedirectResponse { $global = BotConfig::globalBot(); if ($global !